<?php
declare(strict_types=1);
$configFile=dirname(__DIR__).'/config/config.php';
if(!is_file($configFile)){http_response_code(503);exit('Əvvəlcə config/config.php faylını yaradın.');}
$config=require $configFile;
session_name($config['security']['session_name']??'rashadfinance_admin');
session_set_cookie_params(['httponly'=>true,'secure'=>!empty($_SERVER['HTTPS']),'samesite'=>'Strict']);
session_start();
if(empty($_SESSION['rf_admin'])){header('Location: login.php');exit;}
$db=$config['database'];$pdo=new PDO("mysql:host={$db['host']};dbname={$db['name']};charset={$db['charset']}",$db['username'],$db['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
function countRows(PDO $pdo,string $table):int{return (int)$pdo->query("SELECT COUNT(*) FROM `$table`")->fetchColumn();}
$stats=[];foreach(['articles','categories','videos','services','projects','inquiries'] as $t){$stats[$t]=countRows($pdo,$t);}
$recent=$pdo->query("SELECT full_name,email,status,created_at FROM inquiries ORDER BY id DESC LIMIT 6")->fetchAll();
